import random
import math
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        rank = 0
        for j in range(n):
            i_max = rank
            for i in range(rank, m):
                if abs(A[i][j]) > abs(A[i_max][j]):
                    i_max = i
            if A[i_max][j] == 0:
                continue
            A[rank], A[i_max] = A[i_max], A[rank]
            for i in range(m):
                if i != rank:
                    factor = -A[i][j] / A[rank][j]
                    for k in range(n):
                        A[i][k] += factor * A[rank][k]
            rank += 1
        return rank

    def monomial_ideal_rank(n, k):
        # Generate a random k-CLIQUE instance
        vertices = list(range(n))
        edges = set()
        for _ in range(k):
            u = random.choice(vertices)
            v = random.choice(vertices)
            if u != v and (u, v) not in edges and (v, u) not in edges:
                edges.add((u, v))

        # Construct the associated monomial ideal
        I = []
        for edge in edges:
            i, j = edge
            monomial = [0] * n
            monomial[i] = 1
            monomial[j] = 1
            I.append(monomial)

        # Compute the tropical curve rank
        A = [[max(I[i][j], I[j][i]) for j in range(n)] for i in range(n)]
        return gaussian_elimination(A)

    n_min, n_max = 5, 40
    instances_tested = 0
    total_rank = 0

    for n in range(n_min, n_max + 1):
        rank = monomial_ideal_rank(n, k)
