        instances_tested += 1

    mean_rank = Fraction(total_rank, instances_tested)
    f_n = math.log(n_max) * n_max**2
    if mean_rank < f_n:
        return {
            "metric_name": "tropical_curve_rank",
            "metric_value": float(mean_rank),
            "instances_tested": instances_tested,
            "conjecture_holds": False,
